using System;
using System.IO;
using System.Linq;
using CastleFight;
using Newtonsoft.Json.Linq;
using UnityEditor;
using UnityEngine;
public static class BuildFinalRaces {
    static readonly string[] Keys={"nerubian","pandaren","ultimate"},Names={"NerubianSwarm","PandarenOrder","UltimateBuilder"},Builders={"hUAv","hPBu","h075"};
    static GameObject Saved(string raw,string role,int team)=>AssetDatabase.LoadAssetAtPath<GameObject>("Assets/GeneratedPC/"+raw+"-t"+team+".prefab")??BuildClassic.Model(raw,role,team);
    public static void Prepare(){AssetDatabase.Refresh();for(int race=0;race<Keys.Length;race++){
        string key=Keys[race],path="Assets/Resources/"+Names[race]+".asset";var data=JObject.Parse(File.ReadAllText("Assets/Resources/pc-"+key+".json"));var lines=(JArray)data["lines"];int n=lines.Count;var pack=ScriptableObject.CreateInstance<PcRacePack>();pack.catalog=AssetDatabase.LoadAssetAtPath<TextAsset>("Assets/Resources/pc-"+key+".json");pack.units=new GameObject[n*2];pack.buildings=new GameObject[n*2];pack.builders=new GameObject[2];pack.hdUnits=pack.hdBuildings=pack.hdBuilders=Array.Empty<GameObject>();
        for(int team=0;team<2;team++){for(int i=0;i<n;i++){string unit=(string)lines[i]["unit"],raw=(string)lines[i]["building"];if(!string.IsNullOrEmpty(unit)&&unit!="u00F"&&(bool?)lines[i]["stats"]?["hidden_controller"]!=true)pack.units[team*n+i]=Saved(unit,"u",team);pack.buildings[team*n+i]=Saved(raw,"b",team);}pack.builders[team]=Saved(Builders[race],"builder",team);}
        string title=char.ToUpperInvariant(key[0])+key.Substring(1);pack.buildingIcons=lines.Select(l=>BuildPC.Texture("Building-"+(string)l["building"])).ToArray();pack.builderIcon=BuildPC.Texture(title+"Builder");pack.buildIcon=BuildPC.Texture(title+"Build");pack.abilityIds=((JArray)data["raceAbilityIds"]).Select(v=>(string)v).ToArray();pack.abilityIcons=pack.abilityIds.Select(id=>BuildPC.Texture("Ability-"+id)).ToArray();var existing=AssetDatabase.LoadAssetAtPath<PcRacePack>(path);if(existing){EditorUtility.CopySerialized(pack,existing);UnityEngine.Object.DestroyImmediate(pack);EditorUtility.SetDirty(existing);}else AssetDatabase.CreateAsset(pack,path);
    }PrepareEffects();PrepareParticles();RepairSourcePresentation();AssetDatabase.SaveAssets();Validate();Debug.Log("CF_FINAL_RACES_PREPARED classic=true races=3");}
    static void PrepareEffects(){Directory.CreateDirectory("Assets/Resources/FinalFx");Directory.CreateDirectory("Assets/Resources/FinalFxMaterials");AssetDatabase.Refresh();string whitePath="Assets/Resources/FinalFxMaterials/NativeWhite.asset";var whiteTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(whitePath);if(!whiteTexture){whiteTexture=new Texture2D(1,1,TextureFormat.RGBA32,false);whiteTexture.SetPixel(0,0,Color.white);whiteTexture.Apply();AssetDatabase.CreateAsset(whiteTexture,whitePath);}var index=JObject.Parse(File.ReadAllText("Assets/Resources/final-fx-index.json"));var particles=JObject.Parse(File.ReadAllText("Assets/SourceAssets/final-particles.json"));var meshes=((JArray)index["meshes"]).Select(v=>(string)v).ToArray();
        foreach(string key in (JArray)index["available"])for(int team=0;team<2;team++){GameObject root;if(meshes.Contains(key)){var prefab=Saved(key,"fx",team);root=UnityEngine.Object.Instantiate(prefab);}else{root=new GameObject(key+"-"+team);var model=root.AddComponent<PcModel>();model.raw=key;model.animatedRoot=root;model.particleOnly=true;model.clips=Array.Empty<AnimationClip>();}
            if(index["defaultWhite"]?[key] is JArray white)foreach(var renderer in root.GetComponentsInChildren<SkinnedMeshRenderer>())foreach(int i in white){var mat=renderer.sharedMaterials[i];if(!mat.mainTexture){mat.mainTexture=whiteTexture;EditorUtility.SetDirty(mat);}}
            if(particles[key] is JObject profile){var clips=(JObject)profile["clips"];var interval=(JArray)(clips["Stand"]??clips["Birth"]??clips.Properties().First().Value);BuildFinalParticles.Add(root,profile,interval,key+"-"+team);}
            PrefabUtility.SaveAsPrefabAsset(root,"Assets/Resources/FinalFx/"+key+"-"+team+".prefab");UnityEngine.Object.DestroyImmediate(root);
        }
    }
    static void PrepareParticles(){var particles=JObject.Parse(File.ReadAllText("Assets/SourceAssets/final-particles.json"));foreach(var prefab in Names.SelectMany(n=>AssetDatabase.LoadAssetAtPath<PcRacePack>("Assets/Resources/"+n+".asset").Prefabs).Distinct()){
        string raw=prefab.GetComponent<PcModel>().raw;if(!(particles["actor_"+raw] is JObject profile))continue;string path=AssetDatabase.GetAssetPath(prefab);var root=PrefabUtility.LoadPrefabContents(path);foreach(var emitter in root.GetComponentsInChildren<NativeMapEmitter>())UnityEngine.Object.DestroyImmediate(emitter.gameObject);var clips=(JObject)profile["clips"];BuildFinalParticles.Add(root,profile,(JArray)(clips["Stand"]??clips["stand"]??clips.Properties().First().Value),"actor-"+prefab.name);PrefabUtility.SaveAsPrefabAsset(root,path);PrefabUtility.UnloadPrefabContents(root);
    }}
    static void RepairSourcePresentation(){
        var appearance=JObject.Parse(File.ReadAllText("Assets/Resources/native-appearance.json"));var mapping=JObject.Parse(File.ReadAllText("Assets/SourceAssets/classic-models.json"));var tints=JObject.Parse(File.ReadAllText("Assets/SourceAssets/classic-tints.json"));
        var effects=AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Resources/FinalFx"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<GameObject>);
        foreach(var prefab in Names.Take(2).SelectMany(n=>AssetDatabase.LoadAssetAtPath<PcRacePack>("Assets/Resources/"+n+".asset").Prefabs).Concat(new[]{Saved("h075","builder",0),Saved("h075","builder",1),Saved("h076","b",0),Saved("h076","b",1)}).Concat(effects).Distinct()){
            var model=prefab.GetComponent<PcModel>();var surfaces=appearance[model.raw]?["surfaces"] as JArray;var white=(JArray)JObject.Parse(File.ReadAllText("Assets/Resources/final-fx-index.json"))["defaultWhite"]?[model.raw];if(white!=null)foreach(var renderer in prefab.GetComponentsInChildren<SkinnedMeshRenderer>())foreach(int i in white){var mat=renderer.sharedMaterials[i];if(!mat.mainTexture){mat.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Resources/FinalFxMaterials/NativeWhite.asset");EditorUtility.SetDirty(mat);}}
            if(surfaces!=null&&surfaces.Any(v=>v["color"] is JArray))foreach(var renderer in prefab.GetComponentsInChildren<SkinnedMeshRenderer>())for(int i=0;i<renderer.sharedMaterials.Length&&i<surfaces.Count;i++)if(surfaces[i]["color"] is JArray color){var tint=tints[model.raw] as JArray;var value=new Color((float)color[0],(float)color[1],(float)color[2],(float)color[3])*(tint!=null?new Color((float)tint[0],(float)tint[1],(float)tint[2],(float)tint[3]):Color.white);renderer.sharedMaterials[i].SetColor("_Tint",value);EditorUtility.SetDirty(renderer.sharedMaterials[i]);}
            if(model.clips.Any(c=>c&&c.name.StartsWith(model.raw+"-t",StringComparison.Ordinal))){
                string source=(string)mapping[model.raw];if(string.IsNullOrEmpty(source))throw new Exception("Missing clip identity source "+model.raw);var originals=AssetDatabase.LoadAllAssetsAtPath(source).OfType<AnimationClip>().ToArray();if(originals.Length!=model.clips.Length)throw new Exception("Native clip count changed "+model.raw);
                for(int i=0;i<originals.Length;i++){model.clips[i].name=originals[i].name;EditorUtility.SetDirty(model.clips[i]);}
            }
        }
        Debug.Log("CF_FINAL_NATIVE_PRESENTATION_REPAIRED clips=true materialFactors=true");
    }
    public static void Validate(){foreach(string name in Names){var pack=AssetDatabase.LoadAssetAtPath<PcRacePack>("Assets/Resources/"+name+".asset");if(!pack||!pack.catalog)throw new Exception("Missing final race pack "+name);var lines=(JArray)JObject.Parse(pack.catalog.text)["lines"];int n=lines.Count;if(pack.units.Length!=n*2||pack.buildings.Length!=n*2||pack.builders.Length!=2||pack.Prefabs.Count()!=2*(n+lines.Count(l=>!string.IsNullOrEmpty((string)l["unit"])&&(string)l["unit"]!="u00F"&&(bool?)l["stats"]?["hidden_controller"]!=true)+1)||pack.buildingIcons.Length!=n||pack.buildingIcons.Any(v=>!v)||!pack.builderIcon||!pack.buildIcon||pack.abilityIcons.Any(v=>!v))throw new Exception("Incomplete pack "+name);foreach(var prefab in pack.Prefabs.Distinct()){var model=prefab.GetComponent<PcModel>();if(!model||model.reforged||model.godotHeight!=0||!model.animatedRoot||model.clips.Length==0||model.clips.Any(c=>!c))throw new Exception("Invalid classic model "+prefab.name);foreach(var renderer in prefab.GetComponentsInChildren<SkinnedMeshRenderer>())if(renderer.sharedMaterials.Any(m=>!m||!m.shader||!m.mainTexture))throw new Exception("Invalid final model material "+prefab.name);}Debug.Log("CF_"+name.ToUpperInvariant()+"_REFERENCES_PASS rows="+n+" models="+pack.Prefabs.Count());}
        foreach(var path in AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Resources/FinalFx"}).Select(AssetDatabase.GUIDToAssetPath)){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(!prefab.GetComponent<PcModel>())throw new Exception("Missing effect adapter "+path);foreach(var renderer in prefab.GetComponentsInChildren<Renderer>())foreach(var m in renderer.sharedMaterials)if(!m||!m.shader||!m.mainTexture)throw new Exception("Invalid saved native final effect material "+path);}
    }
    public static void FinishAndBuildWindows(){AssetDatabase.Refresh();RepairSourcePresentation();AssetDatabase.SaveAssets();Validate();BuildFullMap.RebuildRuntimeWindows();}
    public static void BuildWindows(){Prepare();BuildFullMap.RebuildRuntimeWindows();}
}
